  /**
   * Reject a PENDING claim with a reason, putting it back to OPEN (still bound by the last statement if
   * that statement counted it). Only a steward or the person's approver rejects; a claim not PENDING or due by a date inside a closed
   * period is refused and nothing changes. Returns the person it belongs to.
   */
  @Transactional
  public long reject(String sheetId, String user, long claimId, String reason) {
      Claim claim = pending(sheetId, user, claimId, "reject", "rejected");
      Rollup.Figures before = rollup.figures(sheetId);
      claim.setStatus(ClaimStatus.OPEN);
      Person owner = people.findByIdAndSheetId(claim.getPersonId(), sheetId).orElse(null);
      log(sheetId, user, claim, owner);
      claims.flush();
      String person = owner == null ? "" : owner.getName();
      events.publishEvent(new ClaimChanged("CLAIM_REJECTED", sheetId, user, person, claim.getAmount(),
              claim.getDate(), claim.getShownNumber(), null, reason));
      rollup.changed(sheetId, user, before);
      return claim.getPersonId();
  }

  /**
 */
protected async move(c: Claim, action: ClaimAction): Promise<void> {
  if (this.busy) return;
  this.claimError.set(null);
  const sheet = this.session.sheet();
  if (!sheet) return;
  const reason = (this.rejectReasons()[c.id] ?? '').trim();
  if (action === 'reject' && reason === '') {
    this.claimError.set({ id: c.id, message: 'Enter a reason to reject the claim.' });
    return;
  }
  const voidReason = this.voidReasons()[c.id] ?? '';
  if (action === 'void' && this.voidReasonList.reasons().length > 0 && !this.voidReasonList.reasons().includes(voidReason)) {
    this.claimError.set({ id: c.id, message: 'Choose a reason to void the claim.' });
    return;
  }
  const on = (this.settleDates()[c.id] ?? '').trim();
  if (action === 'settle') this.settleDates.update((all) => ({ ...all, [c.id]: '' }));
  const headers = { 'X-User': this.session.user() ?? '' };
  this.busy = true;
  try {
    const person = await firstValueFrom(
      this.http.post<PersonWithClaims>(
        `/api/sheets/${encodeURIComponent(sheet)}/claims/${c.id}/${action}`,
        action === 'reject'
          ? { reason }
          : action === 'void'
            ? { reason: voidReason === '' ? null : voidReason }
            : action === 'settle' && on !== ''
              ? { on }
              : null,
        { headers },
      ),
    );
    if (this.session.sheet() !== sheet) return;
    if (action === 'reject') this.rejectReasons.update((all) => ({ ...all, [c.id]: '' }));
    if (action === 'void') this.voidReasons.update((all) => ({ ...all, [c.id]: '' }));
    this.saved.emit(person);
  } catch (err) {
    if (this.session.sheet() !== sheet) return;
    if (err instanceof HttpErrorResponse && err.status === 403) {
      this.claimError.set({ id: c.id, message: err.error?.message || `You opened this claim, so another user must ${action} it.` });
      return;

